def custom_check(series: pd.Series) -> dict:
    import re
    pattern = re.compile(r'^\$?\d{1,3}(,\d{3})*(\.\d+)?[kK]?$')
    total = len(series)
    violations = series.apply(lambda x: not bool(pattern.match(str(x).strip()))).sum()
    if violations == 0:
        return {"passed": True, "metric": "0 violations", "details": "All values conform to quality constraint"}
    return {"passed": False, "metric": f"{violations} / {total} violations", "details": f"{violations} values do not match the required pattern"}

