def custom_check(series: pd.Series) -> dict:
    import re
    pattern = re.compile(r'^\$?\d{1,3}(,\d{3})*(\.\d{2})?$')
    violations = []
    for i, val in enumerate(series):
        if not isinstance(val, str) or not pattern.fullmatch(val.strip()):
            violations.append(f'{i}:{val}')
    passed = len(violations) == 0
    metric = f'{len(violations)} / {len(series)} violations'
    details = 'All values conform to quality constraint' if passed else ', '.join(violations)
    return {'passed': passed, 'metric': metric, 'details': details}

