import pandas as pd
import re
def custom_check(series: pd.Series) -> dict:
    total=len(series)
    violations=0
    pat=re.compile(r'^\d{4}-\d{2}-\d{2}$')
    for v in series.astype(str):
        if not pat.match(v):
            violations+=1
            continue
        try:
            pd.to_datetime(v,format='%Y-%m-%d',errors='raise')
        except Exception:
            violations+=1
    passed=violations==0
    metric=f"{violations} / {total} violations" if not passed else "0 violations"
    details="All values conform to quality constraint" if passed else f"{violations} values cannot be parsed as ISO‑8601 dates"
    return {"passed":passed,"metric":metric,"details":details}

